    ValueCannotCrossIntoScript,
    UnknownValueTag,
    ExpectedStringValue,
    ValueRunsPastBytes,
    NotAnObject,
    NotAFunction,
    LiteralEvaluatedToPrimitive,
    DisplayOptionsNotAnObject,
    EngineGlobalMissing,
    DeferredPromiseNotAList,
    DeferredPromiseIncomplete,
    ObjectCarriesNoState,
    ArgumentNotOfType,
    EventNoLongerValid,
    ArgumentConversionFailed,
    InterfacePropertyConversionFailed,
    InterfacePropertyMissing,
    InterfacePropertyNotFinite,
    VariantConversionFailed,
    TextConversionFailed,
    InfinityNotSupported,
    ArgumentVariantConversionFailed,
    JspModuleArgument,
