    NotAFormBuilderMember,
    FormKitFunctionMissing,
    PackFileNotAnObject,
    ManifestHeaderIncomplete,
    ScriptModuleWithoutUuid,
    TaskDelayNotFinite,
    DebugSessionAlreadyAttached,
    UnhandledDebuggerCommand,
